  'button': Component(
    description:
        "Six variants and four sizes, with leading and trailing icons.",
    requires: ["theme", "pressable", "group"],
    packages: [],
    block: false,
    files: {
      'button.dart':
          r'''// Ashlar UI: Button. Copied into your app by `ashlar add button`; it is yours to change.

import 'package:flutter/widgets.dart';

import 'group.dart';
import 'pressable.dart';
import 'theme.dart';

enum ButtonVariant {
  /// The main action on a screen.
  primary,

  /// A quieter action beside the main one.
  secondary,

  /// An action with a border and no fill.
  outline,

  /// An action with no border or fill until it is hovered: toolbars, menus.
  ghost,

  /// An action that deletes or cannot be undone.
  destructive,

  /// Text that acts like a link.
  link,
}

enum ButtonSize {
  /// 32 tall.
  sm,

  /// 36 tall.
  md,

  /// 40 tall.
  lg,

  /// A 36 square for one icon: give it a semanticLabel.
  icon,

  /// 24 tall, for dense rows.
  xs,

  /// Squares for one icon: 24, 32 and 40.
  iconXs,
  iconSm,
  iconLg,
}

/// A button. [child] is usually a Text; [leading] and [trailing] an icon each side.
///
/// ```dart
/// Button(onPressed: save, child: Text('Save'))
/// Button(variant: ButtonVariant.outline, leading: AshlarIcon(AshlarIconsRoundedStroke.plus), onPressed: add, child: Text('Add'))
/// Button(size: ButtonSize.icon, semanticLabel: 'Settings', onPressed: open, child: AshlarIcon(AshlarIconsRoundedStroke.settings))
/// ```
class Button extends StatelessWidget {
  const Button({
    super.key,
    required this.onPressed,
    required this.child,
    this.variant = ButtonVariant.primary,
    this.size = ButtonSize.md,
    this.leading,
    this.trailing,
    this.focusNode,
    this.autofocus = false,
    this.semanticLabel,
    this.expand = false,
    this.error = false,
  });

  /// Null disables the button.
  final VoidCallback? onPressed;

  /// What it shows: usually a Text, an icon, or both.
  final Widget child;

  /// Its fill: primary for the main action, then secondary, outline, ghost, destructive
  /// or link.
  final ButtonVariant variant;

  /// Its height and room, or a square for an icon alone.
  final ButtonSize size;

  /// Before the label: usually an icon.
  final Widget? leading;

  /// After the label: usually an icon.
  final Widget? trailing;

  /// Its focus node, to move focus to it or follow it from outside; one is made when not
  /// given.
  final FocusNode? focusNode;

  /// Takes the keyboard's focus when it first appears.
  final bool autofocus;

  /// What a screen reader calls it when its visible text does not say, as for an icon
  /// alone.
  final String? semanticLabel;

  /// Fills the width it is given.
  final bool expand;

  /// Draws it as invalid: a destructive border and ring, as on a field.
  final bool error;

  bool get _square =>
      size == ButtonSize.icon ||
      size == ButtonSize.iconXs ||
      size == ButtonSize.iconSm ||
      size == ButtonSize.iconLg;

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    return Pressable(
      onPressed: onPressed,
      focusNode: focusNode,
      autofocus: autofocus,
      semanticLabel: semanticLabel,
      builder: (context, state) {
        final (Color bg, Color fg, Color? border) = switch (variant) {
          ButtonVariant.primary => (
            state.hovered ? c.primary.withValues(alpha: .9) : c.primary,
            c.primaryForeground,
            null,
          ),
          ButtonVariant.secondary => (
            state.hovered ? c.secondary.withValues(alpha: .8) : c.secondary,
            c.secondaryForeground,
            null,
          ),
          ButtonVariant.destructive => (
            state.hovered ? c.destructive.withValues(alpha: .9) : c.destructive,
            c.destructiveForeground,
            null,
          ),
          ButtonVariant.outline => (
            state.hovered ? c.accent : c.background,
            state.hovered ? c.accentForeground : c.foreground,
            c.input,
          ),
          ButtonVariant.ghost => (
            state.hovered ? c.accent : c.accent.withValues(alpha: 0),
            state.hovered ? c.accentForeground : c.foreground,
            null,
          ),
          ButtonVariant.link => (const Color(0x00000000), c.primary, null),
        };
        final (double standard, double padding, double gap) = switch (size) {
          ButtonSize.sm => (32.0, 12.0, 6.0),
          ButtonSize.md => (36.0, 16.0, 8.0),
          ButtonSize.lg => (40.0, 24.0, 8.0),
          ButtonSize.icon => (36.0, 0.0, 0.0),
          ButtonSize.xs => (24.0, 8.0, 4.0),
          ButtonSize.iconXs => (24.0, 0.0, 0.0),
          ButtonSize.iconSm => (32.0, 0.0, 0.0),
          ButtonSize.iconLg => (40.0, 0.0, 0.0),
        };
        // Taller or shorter with the theme's density.
        final height = t.control(standard);
        final label = DefaultTextStyle.merge(
          style: (size == ButtonSize.xs ? t.text.xs : t.text.sm).copyWith(
            color: fg,
            fontWeight: FontWeight.w500,
            decoration: variant == ButtonVariant.link && state.hovered
                ? TextDecoration.underline
                : null,
            decorationColor: fg,
          ),
          maxLines: 1,
          overflow: TextOverflow.ellipsis,
          child: IconTheme.merge(
            data: IconThemeData(color: fg, size: 16),
            // The row sets the height and centres in it; the button hugs it unless [expand].
            child: SizedBox(
              height: height,
              width: _square ? height : null,
              child: Row(
                mainAxisSize: expand ? MainAxisSize.max : MainAxisSize.min,
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  if (leading != null) ...[leading!, SizedBox(width: gap)],
                  Flexible(child: child),
                  if (trailing != null) ...[SizedBox(width: gap), trailing!],
                ],
              ),
            ),
          ),
        );
        return Opacity(
          opacity: state.enabled ? 1 : .5,
          child: AnimatedContainer(
            duration: t.duration,
            padding: EdgeInsets.symmetric(horizontal: padding),
            decoration: BoxDecoration(
              color: bg,
              borderRadius: joinedRadius(context, t.radiusMd),
              border: error
                  ? joinedBorder(context, c.destructive)
                  : border == null
                  ? null
                  : joinedBorder(context, state.focused ? c.ring : border),
              boxShadow: [
                if (state.focused)
                  error
                      ? BoxShadow(
                          color: c.destructive.withValues(alpha: .2),
                          spreadRadius: 3,
                        )
                      : t.focusRing.first,
                if (variant == ButtonVariant.outline ||
                    variant == ButtonVariant.primary ||
                    variant == ButtonVariant.secondary ||
                    variant == ButtonVariant.destructive)
                  ...t.shadowXs,
              ],
            ),
            child: label,
          ),
        );
      },
    );
  }
}
''',
    },
    testNeeds: ["app", "theme"],
    tests: {
      'button_test.dart':
          r'''// Tests for Button. Copied into your app by `ashlar add button` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/button.dart';
import 'package:ashlar_ui_gallery/ui/theme.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

/// These tests measure how controls look, so without the room a finger's press area
/// takes on a phone (tap_target_test.dart covers that).
Widget app(Widget child, {AshlarThemeMode mode = AshlarThemeMode.light}) =>
    AshlarApp(
      theme: AshlarThemeData.light().copyWith(tapTarget: 0),
      darkTheme: AshlarThemeData.dark().copyWith(tapTarget: 0),
      themeMode: mode,
      home: Center(child: child),
    );

/// The decoration of the first box a control draws.
BoxDecoration box(WidgetTester tester, Finder of) =>
    tester
            .widget<AnimatedContainer>(
              find
                  .descendant(of: of, matching: find.byType(AnimatedContainer))
                  .first,
            )
            .decoration!
        as BoxDecoration;

/// These tests measure how controls look, so without the room a finger's press area
/// takes on a phone (tap_target_test.dart covers that).
Widget app2(Widget child) => AshlarApp(
  theme: AshlarThemeData.light().copyWith(tapTarget: 0),
  home: Center(child: child),
);

void main() {
  group('Button', () {
    testWidgets('a tap, Enter and Space all press it', (tester) async {
      var presses = 0;
      await tester.pumpWidget(
        app(Button(onPressed: () => presses++, child: const Text('Save'))),
      );
      await tester.tap(find.text('Save'));
      expect(presses, 1);
      await tester.sendKeyEvent(LogicalKeyboardKey.tab);
      await tester.pump();
      await tester.sendKeyEvent(LogicalKeyboardKey.enter);
      await tester.sendKeyEvent(LogicalKeyboardKey.space);
      expect(presses, 3);
    });

    testWidgets('disabled, it ignores taps and is announced as disabled', (
      tester,
    ) async {
      final semantics = tester.ensureSemantics();
      await tester.pumpWidget(
        app(const Button(onPressed: null, child: Text('Save'))),
      );
      await tester.tap(find.text('Save'), warnIfMissed: false);
      expect(
        tester.getSemantics(find.text('Save')),
        matchesSemantics(
          label: 'Save',
          isButton: true,
          hasEnabledState: true,
          isFocusable: false,
        ),
      );
      semantics.dispose();
    });

    testWidgets('a screen reader hears its text as a button', (tester) async {
      final semantics = tester.ensureSemantics();
      await tester.pumpWidget(
        app(Button(onPressed: () {}, child: const Text('Save'))),
      );
      expect(
        tester.getSemantics(find.text('Save')),
        matchesSemantics(
          label: 'Save',
          isButton: true,
          hasEnabledState: true,
          isEnabled: true,
          hasTapAction: true,
          isFocusable: true,
          hasFocusAction: true,
        ),
      );
      semantics.dispose();
    });

    testWidgets('the focus ring shows for keyboard focus, not for a tap', (
      tester,
    ) async {
      await tester.pumpWidget(
        app(Button(onPressed: () {}, child: const Text('Save'))),
      );
      final button = find.byType(Button);
      bool ring() =>
          box(tester, button).boxShadow!.any((s) => s.spreadRadius == 3);
      await tester.tap(find.text('Save'));
      await tester.pumpAndSettle();
      expect(ring(), isFalse);
      await tester.sendKeyEvent(LogicalKeyboardKey.tab);
      await tester.pumpAndSettle();
      expect(ring(), isTrue);
    });

    testWidgets('hovering changes its fill', (tester) async {
      await tester.pumpWidget(
        app(
          Button(
            variant: ButtonVariant.outline,
            onPressed: () {},
            child: const Text('Save'),
          ),
        ),
      );
      final before = box(tester, find.byType(Button)).color;
      final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
      await mouse.addPointer(location: Offset.zero);
      await mouse.moveTo(tester.getCenter(find.text('Save')));
      await tester.pumpAndSettle();
      expect(box(tester, find.byType(Button)).color, isNot(before));
      expect(box(tester, find.byType(Button)).color, AshlarColors.light.accent);
    });

    testWidgets('every variant and size lays out without overflow', (
      tester,
    ) async {
      await tester.pumpWidget(
        app(
          Wrap(
            children: [
              for (final v in ButtonVariant.values)
                for (final s in ButtonSize.values)
                  Button(
                    variant: v,
                    size: s,
                    onPressed: () {},
                    semanticLabel: 'x',
                    child: const Text('Go'),
                  ),
            ],
          ),
        ),
      );
      expect(tester.takeException(), isNull);
      final heights = [
        for (final e in find.byType(Button).evaluate()) e.size!.height,
      ];
      expect(heights.take(4), [32, 36, 40, 36]);
    });
  });

  testWidgets(
    'button sizes, and an invalid button draws a destructive border',
    (tester) async {
      await tester.pumpWidget(
        app2(
          Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (final s in [
                ButtonSize.xs,
                ButtonSize.iconXs,
                ButtonSize.iconSm,
                ButtonSize.iconLg,
              ])
                Button(
                  size: s,
                  semanticLabel: '$s',
                  onPressed: () {},
                  child: const Text('A'),
                ),
              Button(
                variant: ButtonVariant.outline,
                error: true,
                onPressed: () {},
                child: const Text('Bad'),
              ),
            ],
          ),
        ),
      );
      final sizes = [
        for (final e in find.byType(Button).evaluate().take(4)) e.size!,
      ];
      expect(sizes.map((s) => s.height), [24, 24, 32, 40]);
      expect(sizes.skip(1).map((s) => s.width), [24, 32, 40]);
      final bad = tester.widget<AnimatedContainer>(
        find.descendant(
          of: find.byType(Button).last,
          matching: find.byType(AnimatedContainer),
        ),
      );
      expect(
        ((bad.decoration! as BoxDecoration).border! as Border).top.color,
        AshlarColors.light.destructive,
      );
    },
  );
}
''',
