    packages: ["ashlar_icons"],
    block: false,
    files: {
      'dialog.dart':
          r'''// Ashlar UI: Dialog. Copied into your app by `ashlar add dialog`; it is yours to change.

import 'package:ashlar_icons/ashlar_icons.dart';
import 'package:flutter/widgets.dart';

import 'button.dart';
import 'theme.dart';

/// Opens a dialog above the page and waits for it to close, with what it closed with.
/// The page dims behind it; a tap outside or Escape closes it, unless [dismissible] is false.
///
/// ```dart
/// final ok = await showAshlarDialog<bool>(
///   context: context,
///   builder: (context) => Dialog(
///     title: Text('Delete the file?'),
///     description: Text('This cannot be undone.'),
///     actions: [
///       Button(variant: ButtonVariant.outline, onPressed: () => Navigator.pop(context, false), child: Text('Cancel')),
///       Button(variant: ButtonVariant.destructive, onPressed: () => Navigator.pop(context, true), child: Text('Delete')),
///     ],
///   ),
/// );
/// ```
Future<T?> showAshlarDialog<T>({
  required BuildContext context,
  required WidgetBuilder builder,
  bool dismissible = true,
}) {
  final theme = AshlarTheme.of(context);
  return Navigator.of(context).push<T>(
    RawDialogRoute<T>(
      barrierDismissible: dismissible,
      barrierLabel: 'Close',
      barrierColor: const Color(0x80000000),
      transitionDuration: const Duration(milliseconds: 200),
      // The route is above the app's AshlarTheme, so it carries the theme across.
      pageBuilder: (context, animation, secondary) => AshlarTheme(
        data: theme,
        child: AboveKeyboard(child: Builder(builder: builder)),
      ),
      transitionBuilder: (context, animation, secondary, child) {
        final curved = CurvedAnimation(
          parent: animation,
          curve: Curves.easeOutCubic,
        );
        return FadeTransition(
          opacity: curved,
          child: ScaleTransition(
            scale: Tween(begin: .95, end: 1.0).animate(curved),
            child: child,
          ),
        );
      },
    ),
  );
}

/// The panel a dialog shows: [title], [description], any [content], and [actions] at
/// its foot, with a close button at the top right.
class Dialog extends StatelessWidget {
  const Dialog({
    super.key,
    this.title,
    this.description,
    this.content,
    this.actions = const [],
    this.showClose = true,
    this.maxWidth = 512,
    this.media,
    this.centered = false,
  });

  /// The dialog's title, read first by a screen reader.
  final Widget? title;

  /// A line under the title.
  final Widget? description;

  /// Its body, which scrolls when it is too tall.
  final Widget? content;

  /// Along the bottom, the main one last: usually buttons.
  final List<Widget> actions;

  /// A close button in the corner.
  final bool showClose;

  /// The widest it grows.
  final double maxWidth;

  /// Above the title: an icon on a muted circle, or an image.
  final Widget? media;

  /// Title, description and media centred, and the actions sharing the width: for a short
  /// question in a small dialog.
  final bool centered;

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    return SafeArea(
      child: Center(
        child: Padding(
          padding: const EdgeInsets.all(16),
          child: ConstrainedBox(
            constraints: BoxConstraints(maxWidth: maxWidth),
            child: Semantics(
              scopesRoute: true,
              namesRoute: true,
              explicitChildNodes: true,
              child: Container(
                padding: EdgeInsets.all(t.space(24)),
                decoration: BoxDecoration(
                  color: c.background,
                  borderRadius: BorderRadius.circular(t.radiusLg),
                  border: Border.all(color: c.border),
                  boxShadow: t.shadowLg,
                ),
                child: DefaultTextStyle(
                  style: t.text.sm.copyWith(color: c.foreground),
                  child: Stack(
                    clipBehavior: Clip.none,
                    children: [
                      Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: centered
                            ? CrossAxisAlignment.center
                            : CrossAxisAlignment.stretch,
                        children: [
                          if (media != null) ...[
                            IconTheme.merge(
                              data: IconThemeData(
                                color: c.foreground,
                                size: 24,
                              ),
                              child: Container(
                                width: 48,
                                height: 48,
                                alignment: Alignment.center,
                                decoration: BoxDecoration(
                                  color: c.muted,
                                  shape: BoxShape.circle,
                                ),
                                child: media,
                              ),
                            ),
                            const SizedBox(height: 16),
                          ],
                          if (title != null)
                            Padding(
                              padding: EdgeInsetsDirectional.only(
                                end: showClose && !centered ? 24 : 0,
                              ),
                              child: Semantics(
                                header: true,
                                child: DefaultTextStyle.merge(
                                  style: t.text.lg.copyWith(
                                    fontWeight: FontWeight.w600,
                                    height: 1.2,
                                  ),
                                  textAlign: centered ? TextAlign.center : null,
                                  child: title!,
                                ),
                              ),
                            ),
                          if (description != null) ...[
                            const SizedBox(height: 8),
                            DefaultTextStyle.merge(
                              style: TextStyle(color: c.mutedForeground),
                              textAlign: centered ? TextAlign.center : null,
                              child: description!,
                            ),
                          ],
                          // Long content scrolls; the title and the actions stay in view.
                          if (content != null) ...[
                            const SizedBox(height: 16),
                            Flexible(
                              child: SingleChildScrollView(child: content!),
                            ),
                          ],
                          if (actions.isNotEmpty) ...[
                            const SizedBox(height: 16),
                            if (centered)
                              Row(
                                children: [
                                  for (final (i, a) in actions.indexed) ...[
                                    if (i > 0) const SizedBox(width: 8),
                                    Expanded(child: a),
                                  ],
                                ],
                              )
                            else
                              Wrap(
                                alignment: WrapAlignment.end,
                                spacing: 8,
                                runSpacing: 8,
                                children: actions,
                              ),
                          ],
                        ],
                      ),
                      if (showClose)
                        PositionedDirectional(
                          top: -12,
                          end: -12,
                          child: Button(
                            variant: ButtonVariant.ghost,
                            size: ButtonSize.icon,
                            semanticLabel: 'Close',
                            onPressed: () => Navigator.maybePop(context),
                            child: AshlarIcon(
                              AshlarIconsRoundedStroke.x,
                              color: c.mutedForeground,
                            ),
                          ),
                        ),
                    ],
                  ),
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app", "button", "input", "theme"],
    tests: {
      'dialog_test.dart':
          r'''// Tests for Dialog. Copied into your app by `ashlar add dialog` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/button.dart';
import 'package:ashlar_ui_gallery/ui/dialog.dart';
import 'package:ashlar_ui_gallery/ui/input.dart';
import 'package:ashlar_ui_gallery/ui/theme.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

/// These tests measure how controls look, so without the room a finger's press area
/// takes on a phone (tap_target_test.dart covers that).
Widget app(Widget child, {AshlarThemeMode mode = AshlarThemeMode.light}) =>
    AshlarApp(
      theme: AshlarThemeData.light().copyWith(tapTarget: 0),
      darkTheme: AshlarThemeData.dark().copyWith(tapTarget: 0),
      themeMode: mode,
      home: Center(child: child),
    );

Future<void> open(WidgetTester tester, void Function(BuildContext) show) async {
  tester.view.physicalSize = const Size(400, 800);
  tester.view.devicePixelRatio = 1;
  // A keyboard 300 tall.
  tester.view.viewInsets = const FakeViewPadding(bottom: 300);
  addTearDown(tester.view.reset);
  await tester.pumpWidget(
    AshlarApp(
      home: Builder(
        builder: (context) => Center(
          child: Button(
            onPressed: () => show(context),
            child: const Text('Open'),
          ),
        ),
      ),
    ),
  );
  await tester.tap(find.text('Open'));
  await tester.pumpAndSettle();
}

void main() {
  group('Dialog', () {
    Future<List<Object?>> open(WidgetTester tester) async {
      final results = <Object?>[];
      await tester.pumpWidget(
        app(
          Builder(
            builder: (context) => Button(
              onPressed: () async => results.add(
                await showAshlarDialog<String>(
                  context: context,
                  builder: (context) => Dialog(
                    title: const Text('Delete?'),
                    description: const Text('This cannot be undone.'),
                    actions: [
                      Button(
                        onPressed: () => Navigator.pop(context, 'delete'),
                        child: const Text('Delete'),
                      ),
                    ],
                  ),
                ),
              ),
              child: const Text('Open'),
            ),
          ),
        ),
      );
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsOneWidget);
      return results;
    }

    testWidgets('an action closes it with its value', (tester) async {
      final results = await open(tester);
      await tester.tap(find.text('Delete'));
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsNothing);
      expect(results, ['delete']);
    });

    testWidgets('Escape closes it', (tester) async {
      final results = await open(tester);
      await tester.sendKeyEvent(LogicalKeyboardKey.escape);
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsNothing);
      expect(results, [null]);
    });

    testWidgets('the close button and a tap outside close it', (tester) async {
      await open(tester);
      await tester.tap(find.bySemanticsLabel('Close').last);
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsNothing);
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();
      await tester.tapAt(const Offset(5, 5));
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsNothing);
    });

    testWidgets('it carries the dark theme', (tester) async {
      await tester.pumpWidget(
        app(
          Builder(
            builder: (context) => Button(
              onPressed: () => showAshlarDialog(
                context: context,
                builder: (_) => const Dialog(title: Text('Hi')),
              ),
              child: const Text('Open'),
            ),
          ),
          mode: AshlarThemeMode.dark,
        ),
      );
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();
      final panel = tester.widget<Container>(
        find
            .ancestor(of: find.text('Hi'), matching: find.byType(Container))
            .first,
      );
      expect(
        (panel.decoration! as BoxDecoration).color,
        AshlarColors.dark.background,
      );
    });
  });

  testWidgets('a dialog with a field sits above the keyboard', (tester) async {
    await open(
      tester,
      (context) => showAshlarDialog<void>(
        context: context,
        builder: (_) => const Dialog(
          title: Text('Rename'),
          content: Input(placeholder: 'Name'),
        ),
      ),
    );
    expect(tester.getRect(find.byType(Dialog)).bottom, lessThanOrEqualTo(500));
    expect(tester.getRect(find.byType(Input)).bottom, lessThanOrEqualTo(500));
  });
}
