      'radio.dart':
          r'''// Ashlar UI: Radio. Copied into your app by `ashlar add radio`; it is yours to change.
//
// Flutter's widgets layer has the group: RadioGroup holds the chosen value, and moves the
// choice with the arrow keys. This file draws the radios inside it.

import 'package:flutter/widgets.dart';

import 'theme.dart';

/// One choice in a [RadioGroup]. With a [label] the whole row picks it, and a screen
/// reader hears the label.
///
/// ```dart
/// RadioGroup<String>(
///   groupValue: plan,
///   onChanged: (v) => setState(() => plan = v),
///   child: Column(children: [
///     Radio(value: 'monthly', label: Text('Monthly')),
///     Radio(value: 'yearly', label: Text('Yearly'), description: Text('Two months free.')),
///   ]),
/// )
/// ```
class Radio<T> extends StatefulWidget {
  const Radio({
    super.key,
    required this.value,
    this.label,
    this.description,
    this.enabled = true,
    this.focusNode,
    this.autofocus = false,
    this.card = false,
    this.error = false,
  });

  /// The value it stands for, given back when it is chosen.
  final T value;

  /// Beside the radio button.
  final Widget? label;

  /// A line under the label.
  final Widget? description;

  /// False fades it and stops it taking presses and focus.
  final bool enabled;

  /// Its focus node, to move focus to it or follow it from outside; one is made when not
  /// given.
  final FocusNode? focusNode;

  /// Takes the keyboard's focus when it first appears.
  final bool autofocus;

  /// Drawn as a card to choose: a border round it, marked when chosen.
  final bool card;

  /// Draws it as invalid.
  final bool error;

  @override
  State<Radio<T>> createState() => _RadioState<T>();
}

class _RadioState<T> extends State<Radio<T>> {
  FocusNode? _ownFocus;
  FocusNode get _focus => widget.focusNode ?? (_ownFocus ??= FocusNode());

  @override
  void dispose() {
    _ownFocus?.dispose();
    super.dispose();
  }

  // Its own size, at the start, even where its parent stretches what it holds; a card
  // fills the width it is given.
  @override
  Widget build(BuildContext context) => widget.card
      ? _control(context)
      : Align(
          alignment: AlignmentDirectional.centerStart,
          widthFactor: 1,
          heightFactor: 1,
          child: _control(context),
        );

  Widget _control(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    final registry = RadioGroup.maybeOf<T>(context);
    return RawRadio<T>(
      value: widget.value,
      mouseCursor: WidgetStateProperty.resolveWith(
        (s) => s.contains(WidgetState.disabled)
            ? SystemMouseCursors.basic
            : SystemMouseCursors.click,
      ),
      toggleable: false,
      focusNode: _focus,
      autofocus: widget.autofocus,
      groupRegistry: registry,
      enabled: widget.enabled && registry != null,
      builder: (context, state) {
        final chosen = state.value ?? false;
        final focused = state.states.contains(WidgetState.focused);
        final enabled = !state.states.contains(WidgetState.disabled);
        final dot = AnimatedContainer(
          duration: t.duration,
          width: 16,
          height: 16,
          decoration: BoxDecoration(
            // Opaque, so the shadow beneath does not show through.
            color: c.background,
            shape: BoxShape.circle,
            border: Border.all(
              color: widget.error
                  ? c.destructive
                  : (focused ? c.ring : c.input),
            ),
            boxShadow: [if (focused) ...t.focusRing, ...t.shadowXs],
          ),
          alignment: Alignment.center,
          child: AnimatedScale(
            duration: t.duration,
            scale: chosen ? 1 : 0,
            child: Container(
              width: 8,
              height: 8,
              decoration: BoxDecoration(
                color: c.primary,
                shape: BoxShape.circle,
              ),
            ),
          ),
        );
        final body = widget.label == null && widget.description == null
            ? dot
            : Row(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  Padding(padding: const EdgeInsets.only(top: 2), child: dot),
                  const SizedBox(width: 12),
                  Flexible(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        if (widget.label != null)
                          DefaultTextStyle.merge(
                            style: t.text.sm.copyWith(
                              color: c.foreground,
                              fontWeight: FontWeight.w500,
                            ),
                            child: widget.label!,
                          ),
                        if (widget.description != null)
                          DefaultTextStyle.merge(
                            style: t.text.sm.copyWith(color: c.mutedForeground),
                            child: widget.description!,
                          ),
                      ],
                    ),
                  ),
                ],
              );
        return Opacity(
          opacity: enabled ? 1 : .5,
          child: widget.card
              ? AnimatedContainer(
                  duration: t.duration,
                  padding: const EdgeInsets.all(16),
                  decoration: BoxDecoration(
                    color: chosen
                        ? c.primary.withValues(alpha: .05)
                        : c.primary.withValues(alpha: 0),
                    borderRadius: BorderRadius.circular(t.radiusMd),
                    border: Border.all(color: chosen ? c.primary : c.border),
                  ),
                  child: body,
                )
              : body,
        );
      },
    );
  }
}
''',
    },
    testNeeds: ["app"],
    tests: {
      'radio_test.dart':
          r'''// Tests for Radio. Copied into your app by `ashlar add radio` with the component: they
// check what it promises, so change them as you change it.
import 'dart:ui' show CheckedState;

import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/radio.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child, {AshlarThemeMode mode = AshlarThemeMode.light}) =>
    AshlarApp(
      themeMode: mode,
      home: Center(child: child),
    );

Widget app2(Widget child) => AshlarApp(home: Center(child: child));

void main() {
  group('Radio', () {
    Widget group(String? value, ValueChanged<String?> onChanged) =>
        RadioGroup<String>(
          groupValue: value,
          onChanged: onChanged,
          child: const Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Radio(value: 'monthly', label: Text('Monthly')),
              Radio(value: 'yearly', label: Text('Yearly')),
              Radio(value: 'never', label: Text('Never'), enabled: false),
            ],
          ),
        );

    testWidgets(
      'a tap on the label chooses it, and it is announced as checked',
      (tester) async {
        final semantics = tester.ensureSemantics();
        String? value;
        await tester.pumpWidget(
          app(
            StatefulBuilder(
              builder: (context, set) =>
                  group(value, (v) => set(() => value = v)),
            ),
          ),
        );
        await tester.tap(find.text('Yearly'));
        await tester.pump();
        expect(value, 'yearly');
        final node = tester.getSemantics(find.text('Yearly'));
        expect(node.label, 'Yearly');
        expect(node.flagsCollection.isChecked, CheckedState.isTrue);
        expect(node.flagsCollection.isInMutuallyExclusiveGroup, isTrue);
        semantics.dispose();
      },
    );

    testWidgets('the arrow keys move the choice', (tester) async {
      String? value = 'monthly';
      await tester.pumpWidget(
        app(
          StatefulBuilder(
            builder: (context, set) =>
                group(value, (v) => set(() => value = v)),
          ),
        ),
      );
      await tester.sendKeyEvent(LogicalKeyboardKey.tab);
      await tester.pump();
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowDown);
      await tester.pump();
      expect(value, 'yearly');
    });

    testWidgets('a disabled one cannot be chosen', (tester) async {
      String? value;
      await tester.pumpWidget(
        app(
          StatefulBuilder(
            builder: (context, set) =>
                group(value, (v) => set(() => value = v)),
          ),
        ),
      );
      await tester.tap(find.text('Never'), warnIfMissed: false);
      await tester.pump();
      expect(value, isNull);
    });
  });

  testWidgets('radio cards mark the chosen one', (tester) async {
    String? plan = 'pro';
    await tester.pumpWidget(
      app2(
        SizedBox(
          width: 300,
          child: StatefulBuilder(
            builder: (context, set) => RadioGroup<String>(
              groupValue: plan,
              onChanged: (v) => set(() => plan = v),
              child: const Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  Radio(value: 'free', card: true, label: Text('Free')),
                  Radio(value: 'pro', card: true, label: Text('Pro')),
                ],
              ),
            ),
          ),
        ),
      ),
    );
    await tester.tap(find.text('Free'));
    await tester.pumpAndSettle();
    expect(plan, 'free');
  });
}
