  'accordion': Component(
    description: "Sections that open one at a time under their headings.",
    requires: ["theme", "pressable", "collapsible"],
    packages: ["ashlar_icons"],
    block: false,
    files: {
      'accordion.dart':
          r'''// Ashlar UI: Accordion. Copied into your app by `ashlar add accordion`; it is yours to change.

import 'package:ashlar_icons/ashlar_icons.dart';
import 'package:flutter/widgets.dart';

import 'collapsible.dart';
import 'pressable.dart';
import 'theme.dart';

/// One section of an [Accordion]: its heading and what opens under it.
@immutable
class AccordionItem {
  const AccordionItem({
    required this.title,
    required this.content,
    this.enabled = true,
  });

  /// The heading that opens and closes it.
  final Widget title;

  /// What shows when it is open.
  final Widget content;

  /// False keeps it shut, its heading faded.
  final bool enabled;
}

/// Sections stacked one above the other, each opening under its heading. One open at a
/// time, or any number with [multiple]. A screen reader hears each heading as a button
/// that is expanded or collapsed.
///
/// ```dart
/// Accordion(items: [
///   AccordionItem(title: Text('Can I change the components?'), content: Text('Yes. They are files in your app.')),
///   AccordionItem(title: Text('Does it use Material?'), content: Text('No. Only Flutter\'s widgets layer.')),
/// ])
/// ```
class Accordion extends StatefulWidget {
  const Accordion({
    super.key,
    required this.items,
    this.multiple = false,
    this.initiallyOpen = const {},
    this.bordered = false,
  });

  /// The items, top to bottom.
  final List<AccordionItem> items;

  /// Several may be open at once, not one.
  final bool multiple;

  /// The sections open at first, by index.
  final Set<int> initiallyOpen;

  /// In a box with rounded corners, the open section on a muted ground.
  final bool bordered;

  @override
  State<Accordion> createState() => _AccordionState();
}

class _AccordionState extends State<Accordion> {
  late final Set<int> _open = {...widget.initiallyOpen};

  void _toggle(int i) => setState(() {
    if (_open.contains(i)) {
      _open.remove(i);
    } else {
      if (!widget.multiple) _open.clear();
      _open.add(i);
    }
  });

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    final pad = widget.bordered ? 16.0 : 0.0;
    final column = Column(
      mainAxisSize: MainAxisSize.min,
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        for (final (i, item) in widget.items.indexed)
          AnimatedContainer(
            duration: t.duration,
            padding: EdgeInsets.symmetric(horizontal: pad),
            decoration: BoxDecoration(
              color: widget.bordered && _open.contains(i)
                  ? c.muted.withValues(alpha: c.muted.a * .5)
                  : c.muted.withValues(alpha: 0),
              border: Border(
                bottom: BorderSide(
                  color: i == widget.items.length - 1
                      ? const Color(0x00000000)
                      : c.border,
                ),
              ),
            ),
            child: Collapsible(
              open: _open.contains(i),
              builder: (context, open, _) => Pressable(
                onPressed: item.enabled ? () => _toggle(i) : null,
                expanded: open,
                builder: (context, state) => AnimatedContainer(
                  duration: t.duration,
                  padding: const EdgeInsets.symmetric(vertical: 16),
                  decoration: BoxDecoration(
                    borderRadius: BorderRadius.circular(t.radiusMd),
                    boxShadow: [if (state.focused) ...t.focusRing],
                  ),
                  child: Row(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Expanded(
                        child: DefaultTextStyle.merge(
                          style: t.text.sm.copyWith(
                            color: item.enabled
                                ? c.foreground
                                : c.mutedForeground,
                            fontWeight: FontWeight.w500,
                            decoration: state.hovered && item.enabled
                                ? TextDecoration.underline
                                : null,
                            decorationColor: c.foreground,
                          ),
                          child: item.title,
                        ),
                      ),
                      const SizedBox(width: 16),
                      AnimatedRotation(
                        turns: open ? .5 : 0,
                        duration: t.duration,
                        child: AshlarIcon(
                          AshlarIconsRoundedStroke.chevronDown,
                          size: 16,
                          color: c.mutedForeground,
                        ),
                      ),
                    ],
                  ),
                ),
              ),
              child: Padding(
                padding: const EdgeInsets.only(bottom: 16),
                child: DefaultTextStyle.merge(
                  style: TextStyle(color: c.foreground),
                  child: item.content,
                ),
              ),
            ),
          ),
      ],
    );
    if (!widget.bordered) return column;
    return Container(
      clipBehavior: Clip.antiAlias,
      decoration: BoxDecoration(
        borderRadius: BorderRadius.circular(t.radiusLg),
        border: Border.all(color: c.border),
      ),
      child: column,
    );
  }
}
''',
    },
    testNeeds: ["app"],
    tests: {
      'accordion_test.dart':
          r'''// Tests for Accordion. Copied into your app by `ashlar add accordion` with the component: they
// check what it promises, so change them as you change it.
import 'dart:ui' show Tristate;

import 'package:ashlar_ui_gallery/ui/accordion.dart';
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

void main() {
  group('Accordion', () {
    const items = [
      AccordionItem(title: Text('One'), content: Text('First body')),
      AccordionItem(title: Text('Two'), content: Text('Second body')),
    ];

    testWidgets('one open at a time; the heading says expanded or collapsed', (
      tester,
    ) async {
      final semantics = tester.ensureSemantics();
      await tester.pumpWidget(
        app(const SizedBox(width: 300, child: Accordion(items: items))),
      );
      await tester.tap(find.text('One'));
      await tester.pumpAndSettle();
      expect(find.text('First body').hitTestable(), findsOneWidget);
      expect(
        tester
            .getSemantics(find.text('One'))
            .getSemanticsData()
            .flagsCollection
            .isExpanded,
        Tristate.isTrue,
      );
      expect(
        tester
            .getSemantics(find.text('Two'))
            .getSemanticsData()
            .flagsCollection
            .isExpanded,
        Tristate.isFalse,
      );
      await tester.tap(find.text('Two'));
      await tester.pumpAndSettle();
      expect(find.text('First body').hitTestable(), findsNothing);
      expect(find.text('Second body').hitTestable(), findsOneWidget);
      semantics.dispose();
    });

    testWidgets(
      'with multiple, several stay open; Enter opens from the keyboard',
      (tester) async {
        await tester.pumpWidget(
          app(
            const SizedBox(
              width: 300,
              child: Accordion(items: items, multiple: true),
            ),
          ),
        );
        await tester.sendKeyEvent(LogicalKeyboardKey.tab);
        await tester.sendKeyEvent(LogicalKeyboardKey.enter);
        await tester.pumpAndSettle();
