  'alert-dialog': Component(
    description: "A question that needs an answer before going on.",
    requires: ["dialog", "button"],
    packages: [],
    block: false,
    files: {
      'alert_dialog.dart':
          r'''// Ashlar UI: Alert Dialog. Copied into your app by `ashlar add alert-dialog`; it is yours to
// change.

import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import 'button.dart';
import 'dialog.dart';

/// Asks a question that needs an answer before going on: deleting, leaving with unsaved
/// work. Unlike a Dialog it has no close button and a tap outside does nothing; Escape
/// counts as [cancel]. Returns true for [action], false for anything else.
///
/// ```dart
/// if (await showAlertDialog(context, title: 'Delete the project?', description: 'This cannot be undone.', action: 'Delete', destructive: true)) {
///   delete();
/// }
/// ```
Future<bool> showAlertDialog(
  BuildContext context, {
  required String title,
  String? description,
  String cancel = 'Cancel',
  String action = 'Continue',
  bool destructive = false,
  Widget? media,
  bool small = false,
}) async =>
    await showAshlarDialog<bool>(
      context: context,
      dismissible: false,
      builder: (context) => AlertDialog(
        title: title,
        description: description,
        cancel: cancel,
        action: action,
        destructive: destructive,
        media: media,
        small: small,
      ),
    ) ??
    false;

/// The panel [showAlertDialog] shows.
class AlertDialog extends StatelessWidget {
  const AlertDialog({
    super.key,
    required this.title,
    this.description,
    this.cancel = 'Cancel',
    this.action = 'Continue',
    this.destructive = false,
    this.media,
    this.small = false,
  });

  /// The question or warning.
  final String title;

  /// What happens next, in a line or two.
  final String? description;

  /// The button that does not.
  final String cancel;

  /// The button that does it.
  final String action;

  /// Draws the action in the destructive colour, for what cannot be undone.
  final bool destructive;

  /// An icon above the title, on a muted circle.
  final Widget? media;

  /// Narrow and centred, the two buttons sharing the width.
  final bool small;

  @override
  Widget build(BuildContext context) => CallbackShortcuts(
    bindings: {
      const SingleActivator(LogicalKeyboardKey.escape): () =>
          Navigator.pop(context, false),
    },
    child: Focus(
      autofocus: true,
      child: Dialog(
        showClose: false,
        media: media,
        centered: small,
        maxWidth: small ? 320 : 512,
        title: Text(title),
        description: description == null ? null : Text(description!),
        actions: [
          Button(
            variant: ButtonVariant.outline,
            onPressed: () => Navigator.pop(context, false),
            child: Text(cancel),
          ),
          Button(
            variant: destructive
                ? ButtonVariant.destructive
                : ButtonVariant.primary,
            onPressed: () => Navigator.pop(context, true),
            child: Text(action),
          ),
        ],
      ),
    ),
  );
}
''',
    },
    testNeeds: ["app", "button"],
    tests: {
      'alert_dialog_test.dart':
          r'''// Tests for Alert Dialog. Copied into your app by `ashlar add alert-dialog` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_icons/ashlar_icons.dart';
import 'package:ashlar_ui_gallery/ui/alert_dialog.dart';
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/button.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

void main() {
  group('Alert Dialog', () {
    Future<List<bool>> open(WidgetTester tester) async {
      final answers = <bool>[];
      await tester.pumpWidget(
        app(
          Builder(
            builder: (context) => Button(
              onPressed: () async => answers.add(
                await showAlertDialog(
                  context,
                  title: 'Delete?',
                  action: 'Delete',
                  destructive: true,
                ),
              ),
              child: const Text('Open'),
            ),
          ),
        ),
      );
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();
      return answers;
    }

    testWidgets('a tap outside does nothing; Escape cancels', (tester) async {
      final answers = await open(tester);
      await tester.tapAt(const Offset(5, 5));
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsOneWidget);
      expect(find.bySemanticsLabel('Close'), findsNothing);
      await tester.sendKeyEvent(LogicalKeyboardKey.escape);
      await tester.pumpAndSettle();
      expect(find.text('Delete?'), findsNothing);
      expect(answers, [false]);
    });

    testWidgets('the action answers true', (tester) async {
      final answers = await open(tester);
      await tester.tap(find.text('Delete').last);
      await tester.pumpAndSettle();
      expect(answers, [true]);
    });
  });

  testWidgets(
    'a small alert dialog is centred, its buttons sharing the width',
    (tester) async {
      await tester.pumpWidget(
        app(
          Builder(
            builder: (context) => Button(
              onPressed: () => showAlertDialog(
                context,
                title: 'Leave?',
                small: true,
                media: const AshlarIcon(AshlarIconsRoundedStroke.info),
              ),
              child: const Text('Open'),
            ),
          ),
        ),
      );
      await tester.tap(find.text('Open'));
      await tester.pumpAndSettle();
      final cancel = tester.getRect(find.text('Cancel').first),
          go = tester.getRect(find.text('Continue'));
      expect(tester.getCenter(find.text('Leave?')).dx, closeTo(400, 1));
      expect(cancel.center.dy, go.center.dy);
      expect(
        tester
            .getSize(
              find
                  .ancestor(
                    of: find.text('Cancel'),
                    matching: find.byType(Button),
                  )
                  .first,
            )
            .width,
        greaterThan(100),
      );
    },
  );
}
''',
