  'hover-card': Component(
    description: "A card that appears when the pointer rests on something.",
    requires: ["theme", "popover"],
    packages: [],
    block: false,
    files: {
      'hover_card.dart':
          r'''// Ashlar UI: Hover Card. Copied into your app by `ashlar add hover-card`; it is yours to
// change.

import 'dart:async';

import 'package:flutter/widgets.dart';

import 'popover.dart';
import 'theme.dart';

/// A card that appears when the pointer rests on [child], the keyboard focuses it, or a
/// finger long presses it: a preview of a profile or a link. It is extra: anything a
/// person needs should be reachable without it.
///
/// ```dart
/// HoverCard(
///   content: (context) => Text('Wanjiru Mwangi. Designer at Mittolabs.'),
///   child: Button(variant: ButtonVariant.link, onPressed: openProfile, child: Text('@wanjiru')),
/// )
/// ```
class HoverCard extends StatefulWidget {
  const HoverCard({
    super.key,
    required this.child,
    required this.content,
    this.openDelay = const Duration(milliseconds: 700),
    this.closeDelay = const Duration(milliseconds: 300),
    this.side = PopoverSide.bottom,
    this.align = PopoverAlign.center,
    this.width = 256,
  });

  /// What is hovered or focused to open it.
  final Widget child;

  /// What the card shows.
  final WidgetBuilder content;

  /// How long the pointer rests before it opens.
  final Duration openDelay;

  /// How long it stays after the pointer leaves, so the pointer can reach it.
  final Duration closeDelay;

  /// Which side it opens on. It moves to the other side when there is no room.
  final PopoverSide side;

  /// How it lines up along that side: at the start, the centre or the end.
  final PopoverAlign align;

  /// Its width, in logical pixels.
  final double width;

  @override
  State<HoverCard> createState() => _HoverCardState();
}

class _HoverCardState extends State<HoverCard> {
  final _menu = MenuController();
  Timer? _timer;

  void _later(Duration delay, VoidCallback then) {
    _timer?.cancel();
    _timer = Timer(delay, () {
      if (mounted) then();
    });
  }

  void _show() => _later(widget.openDelay, _menu.open);
  void _hide() => _later(widget.closeDelay, _menu.close);
  void _stay() => _timer?.cancel();

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    return RawMenuAnchor(
      controller: _menu,
      overlayBuilder: (context, info) => PopoverPanel(
        info: info,
        side: widget.side,
        align: widget.align,
        width: widget.width,
        child: MouseRegion(
          onEnter: (_) => _stay(),
          onExit: (_) => _hide(),
          // Sized to its content, scrolling if the room is shorter than that.
          child: SingleChildScrollView(
            padding: EdgeInsets.all(t.space(16)),
            child: DefaultTextStyle.merge(
              style: t.text.sm,
              child: Builder(builder: widget.content),
            ),
          ),
        ),
      ),
      child: MouseRegion(
        onEnter: (_) => _show(),
        onExit: (_) => _hide(),
        child: Focus(
          canRequestFocus: false,
          skipTraversal: true,
          onFocusChange: (focused) {
            if (!focused) {
              _hide();
            } else if (FocusManager.instance.highlightMode ==
                FocusHighlightMode.traditional) {
              _show();
            }
          },
          // Where there is no hover, as on a touch screen, a long press opens it; a tap
          // stays with what it is on. Screen readers get the long press as an action.
          child: GestureDetector(
            onLongPress: () {
              _timer?.cancel();
              _menu.open();
            },
            child: widget.child,
          ),
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app", "button"],
    tests: {
      'hover_card_test.dart':
          r'''// Tests for Hover Card. Copied into your app by `ashlar add hover-card` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/button.dart';
import 'package:ashlar_ui_gallery/ui/hover_card.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

Future<TestGesture> mouseAt(WidgetTester tester, Offset at) async {
  final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
  await mouse.addPointer(location: Offset.zero);
  await mouse.moveTo(at);
  return mouse;
}

void main() {
  testWidgets(
    'a hover card waits, appears, stays while the pointer is on it, then goes',
    (tester) async {
      await tester.pumpWidget(
        app(
          HoverCard(
            content: (context) => const Text('Profile card'),
            child: Button(
              variant: ButtonVariant.link,
              onPressed: () {},
              child: const Text('@wanjiru'),
            ),
          ),
        ),
      );
      final mouse = await mouseAt(
        tester,
        tester.getCenter(find.text('@wanjiru')),
      );
      await tester.pump(const Duration(milliseconds: 300));
      expect(find.text('Profile card'), findsNothing);
      await tester.pump(const Duration(milliseconds: 500));
      await tester.pumpAndSettle();
      expect(find.text('Profile card'), findsOneWidget);
      // Across the gap and onto the card: it stays.
      await mouse.moveTo(tester.getCenter(find.text('Profile card')));
      await tester.pump(const Duration(seconds: 1));
      expect(find.text('Profile card'), findsOneWidget);
      await mouse.moveTo(Offset.zero);
      await tester.pump(const Duration(milliseconds: 400));
      await tester.pumpAndSettle();
      expect(find.text('Profile card'), findsNothing);
    },
  );

  testWidgets('a long press opens it; a tap is the link\'s', (tester) async {
    var went = 0;
    await tester.pumpWidget(
      AshlarApp(
        home: Center(
          child: HoverCard(
            content: (context) => const Text('Joined in March 2024.'),
            child: Button(
              variant: ButtonVariant.link,
              onPressed: () => went++,
              child: const Text('@achieng'),
            ),
          ),
        ),
      ),
    );
    await tester.tap(find.text('@achieng'));
    await tester.pumpAndSettle();
    expect(went, 1);
    expect(find.text('Joined in March 2024.'), findsNothing);
    await tester.longPress(find.text('@achieng'));
    await tester.pumpAndSettle();
    expect(find.text('Joined in March 2024.'), findsOneWidget);
    expect(went, 1);
    // A tap elsewhere closes it.
    await tester.tapAt(const Offset(10, 10));
    await tester.pumpAndSettle();
    expect(find.text('Joined in March 2024.'), findsNothing);
  });
}
''',
    },
  ),
  'context-menu': Component(
    description:
        "A menu that opens where something is right-clicked or long-pressed.",
    requires: ["popover", "dropdown-menu"],
    packages: [],
    block: false,
    files: {
      'context_menu.dart':
          r'''// Ashlar UI: Context Menu. Copied into your app by `ashlar add context-menu`; it is yours to
// change.

import 'package:flutter/foundation.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import 'dropdown_menu.dart';
import 'popover.dart';

/// A menu that opens where [child] is right-clicked or long-pressed, or from the keyboard
/// with the menu key or Shift+F10 while something inside it has focus. Takes the same
/// items as a DropdownMenu. Text inside it cannot be selected: a right-click there is for
/// the menu. On the web it turns the browser's own menu off while shown,
/// when the app fills the page; a page that embeds Flutter in part of it must turn the
/// browser's menu off itself there.
///
/// ```dart
/// ContextMenu(
///   items: [
///     MenuItem(onPressed: back, shortcut: Text('⌘['), child: Text('Back')),
///     MenuItem(onPressed: reload, shortcut: Text('⌘R'), child: Text('Reload')),
///   ],
///   child: Container(height: 150, child: Center(child: Text('Right-click here'))),
/// )
/// ```
class ContextMenu extends StatefulWidget {
  const ContextMenu({
    super.key,
    required this.child,
    required this.items,
    this.width = 224,
  });

  /// What is right-clicked or long pressed to open the menu.
  final Widget child;

  /// [MenuItem], [MenuLabel] and [MenuSeparator], in order.
  final List<Widget> items;

  /// Its width, in logical pixels.
  final double width;

  @override
  State<ContextMenu> createState() => _ContextMenuState();
}

/// How many context menus are on screen, so the browser's menu comes back with the last.
int _shown = 0;

class _ContextMenuState extends State<ContextMenu> {
  final _menu = MenuController();

  @override
  void initState() {
    super.initState();
    // Flutter embedded in a page (a view, not the whole page) cannot turn the browser's
    // menu off and says so with an error; the menu still opens, so the error is dropped.
    if (kIsWeb && _shown++ == 0) {
      BrowserContextMenu.disableContextMenu().catchError((Object _) {});
    }
  }

  @override
  void dispose() {
    if (kIsWeb && --_shown == 0) {
      BrowserContextMenu.enableContextMenu().catchError((Object _) {});
    }
    super.dispose();
  }

  void _openAt(Offset at) => _menu.open(position: at);

  @override
  Widget build(BuildContext context) => RawMenuAnchor(
    controller: _menu,
    overlayBuilder: (context, info) => PopoverPanel(
      info: info,
      width: widget.width,
      child: MenuList(children: widget.items),
    ),
    child: Builder(
      builder: (context) => Shortcuts(
        shortcuts: const {
          SingleActivator(LogicalKeyboardKey.contextMenu): _OpenIntent(),
          SingleActivator(LogicalKeyboardKey.f10, shift: true): _OpenIntent(),
        },
        child: Actions(
          actions: {
            _OpenIntent: CallbackAction<_OpenIntent>(
              onInvoke: (_) {
                final box = context.findRenderObject()! as RenderBox;
                _openAt(box.size.center(Offset.zero));
                return null;
              },
            ),
          },
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onSecondaryTapDown: (d) => _openAt(d.localPosition),
            onLongPressStart: (d) => _openAt(d.localPosition),
            // A right-click or long press here is for the menu, so the text under it is
            // not selected as well.
            child: SelectionContainer.disabled(child: widget.child),
          ),
        ),
      ),
    ),
  );
}

class _OpenIntent extends Intent {
  const _OpenIntent();
}
''',
    },
    testNeeds: ["app", "button", "dropdown-menu", "popover"],
    tests: {
      'context_menu_test.dart':
          r'''// Tests for Context Menu. Copied into your app by `ashlar add context-menu` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/button.dart';
import 'package:ashlar_ui_gallery/ui/context_menu.dart';
import 'package:ashlar_ui_gallery/ui/dropdown_menu.dart';
import 'package:ashlar_ui_gallery/ui/popover.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

void main() {
  group('Context Menu', () {
    Future<List<String>> menu(WidgetTester tester) async {
      final picked = <String>[];
      await tester.pumpWidget(
        app(
          ContextMenu(
            items: [
              MenuItem(
                onPressed: () => picked.add('back'),
                child: const Text('Back'),
              ),
              MenuItem(
                onPressed: () => picked.add('reload'),
                child: const Text('Reload'),
              ),
            ],
            child: SizedBox(
              width: 300,
              height: 150,
              child: Center(
                child: Button(onPressed: () {}, child: const Text('Area')),
              ),
            ),
          ),
        ),
      );
      return picked;
    }

    testWidgets('a right-click opens it at the pointer; picking closes it', (
      tester,
    ) async {
      final picked = await menu(tester);
      final area = tester.getRect(find.byType(ContextMenu));
      final at = area.topLeft + const Offset(40, 30);
      await tester.tapAt(at, buttons: kSecondaryButton);
      await tester.pumpAndSettle();
      final panel = tester.getRect(
        find
            .descendant(
              of: find.byType(PopoverPanel),
              matching: find.byType(TapRegion),
            )
            .first,
      );
      expect(panel.left, closeTo(at.dx, 1));
      expect(panel.top, closeTo(at.dy + 4, 1));
      await tester.tap(find.text('Reload'));
      await tester.pumpAndSettle();
      expect(picked, ['reload']);
      expect(find.text('Back'), findsNothing);
    });

    testWidgets(
      'a long press opens it, and so does Shift+F10 from the keyboard',
      (tester) async {
        await menu(tester);
        await tester.longPress(find.byType(ContextMenu));
        await tester.pumpAndSettle();
        expect(find.text('Back'), findsOneWidget);
        await tester.sendKeyEvent(LogicalKeyboardKey.escape);
        await tester.pumpAndSettle();
        expect(find.text('Back'), findsNothing);
        await tester.sendKeyEvent(LogicalKeyboardKey.tab);
        await tester.pump();
        await tester.sendKeyDownEvent(LogicalKeyboardKey.shiftLeft);
        await tester.sendKeyEvent(LogicalKeyboardKey.f10);
        await tester.sendKeyUpEvent(LogicalKeyboardKey.shiftLeft);
        await tester.pumpAndSettle();
        expect(find.text('Back'), findsOneWidget);
      },
    );
  });
}
''',
    },
  ),
