  'menubar': Component(
    description: "A bar of menus, as at the top of a desktop app.",
    requires: ["theme", "pressable", "popover", "dropdown-menu"],
    packages: [],
    block: false,
    files: {
      'menubar.dart':
          r'''// Ashlar UI: Menubar. Copied into your app by `ashlar add menubar`; it is yours to change.

import 'dart:ui' show SemanticsRole;

import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import 'dropdown_menu.dart';
import 'popover.dart';
import 'pressable.dart';
import 'theme.dart';

/// One menu on a [Menubar]: its name on the bar and its items.
@immutable
class MenubarMenu {
  const MenubarMenu(this.label, {required this.items});

  /// The menu's name in the bar.
  final String label;

  /// [MenuItem], [MenuLabel] and [MenuSeparator], in order.
  final List<Widget> items;
}

/// A bar of menus, as at the top of a desktop app. Once one menu is open, pointing at
/// another opens that one instead, and the left and right arrows move between them.
///
/// ```dart
/// Menubar(menus: [
///   MenubarMenu('File', items: [MenuItem(shortcut: Text('⌘N'), onPressed: newFile, child: Text('New')), ...]),
///   MenubarMenu('Edit', items: [MenuItem(shortcut: Text('⌘Z'), onPressed: undo, child: Text('Undo')), ...]),
/// ])
/// ```
class Menubar extends StatefulWidget {
  const Menubar({super.key, required this.menus});

  /// The menus, in order along the bar.
  final List<MenubarMenu> menus;

  @override
  State<Menubar> createState() => _MenubarState();
}

class _MenubarState extends State<Menubar> {
  late final _menus = [for (final _ in widget.menus) MenuController()];
  late final _focus = [for (final _ in widget.menus) FocusNode()];
  int? _open;

  @override
  void dispose() {
    for (final f in _focus) {
      f.dispose();
    }
    super.dispose();
  }

  void _show(int i) {
    for (final (j, m) in _menus.indexed) {
      if (j != i && m.isOpen) m.close();
    }
    _menus[i].open();
    _focus[i].requestFocus();
  }

  /// Moves [by] menus along the bar: the arrow keys, which swap in right-to-left text.
  void _step(int by) {
    if (isRtl(context)) by = -by;
    _show(
      (((_open ?? 0) + by) % _menus.length + _menus.length) % _menus.length,
    );
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    return Semantics(
      role: SemanticsRole.menuBar,
      container: true,
      explicitChildNodes: true,
      child: Container(
        height: t.control(36),
        padding: const EdgeInsets.all(4),
        decoration: BoxDecoration(
          color: c.background,
          borderRadius: BorderRadius.circular(t.radiusMd),
          border: Border.all(color: c.border),
          boxShadow: t.shadowXs,
        ),
        child: CallbackShortcuts(
          bindings: {
            const SingleActivator(LogicalKeyboardKey.arrowRight): () =>
                _step(1),
            const SingleActivator(LogicalKeyboardKey.arrowLeft): () =>
                _step(-1),
          },
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              for (final (i, menu) in widget.menus.indexed)
                RawMenuAnchor(
                  controller: _menus[i],
                  childFocusNode: _focus[i],
                  onOpen: () => setState(() => _open = i),
                  onClose: () =>
                      setState(() => _open = _open == i ? null : _open),
                  overlayBuilder: (context, info) => PopoverPanel(
                    info: info,
                    minWidth: 192,
                    // The arrows reach the next menu from inside this one too.
                    child: CallbackShortcuts(
                      bindings: {
                        const SingleActivator(
                          LogicalKeyboardKey.arrowRight,
                        ): () =>
                            _step(1),
                        const SingleActivator(
                          LogicalKeyboardKey.arrowLeft,
                        ): () =>
                            _step(-1),
                      },
                      child: MenuList(children: menu.items),
                    ),
                  ),
                  // Inside the anchor: its own arrow keys would otherwise move focus first.
                  child: CallbackShortcuts(
                    bindings: {
                      const SingleActivator(
                        LogicalKeyboardKey.arrowRight,
                      ): () =>
                          _step(1),
                      const SingleActivator(LogicalKeyboardKey.arrowLeft): () =>
                          _step(-1),
                    },
                    child: MouseRegion(
                      onEnter: (_) {
                        if (_open != null && _open != i) _show(i);
                      },
                      child: Pressable(
                        focusNode: _focus[i],
                        role: SemanticsRole.menuItem,
                        expanded: _open == i,
                        onPressed: () =>
                            _open == i ? _menus[i].close() : _show(i),
                        builder: (context, state) => AnimatedContainer(
                          duration: t.duration,
                          padding: const EdgeInsets.symmetric(horizontal: 8),
                          alignment: Alignment.center,
                          decoration: BoxDecoration(
                            color: _open == i || state.hovered || state.focused
                                ? c.accent
                                : c.accent.withValues(alpha: 0),
                            borderRadius: BorderRadius.circular(t.radiusSm),
                          ),
                          child: Text(
                            menu.label,
                            style: t.text.sm.copyWith(
                              fontWeight: FontWeight.w500,
                              color: _open == i || state.hovered
                                  ? c.accentForeground
                                  : c.foreground,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
            ],
          ),
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app", "dropdown-menu"],
    tests: {
      'menubar_test.dart':
          r'''// Tests for Menubar. Copied into your app by `ashlar add menubar` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/dropdown_menu.dart';
import 'package:ashlar_ui_gallery/ui/menubar.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

void main() {
  group('Menubar', () {
    Future<List<String>> bar(WidgetTester tester) async {
      final picked = <String>[];
      await tester.pumpWidget(
        app(
          Menubar(
            menus: [
              MenubarMenu(
                'File',
                items: [
                  MenuItem(
                    onPressed: () => picked.add('new'),
                    child: const Text('New tab'),
                  ),
                ],
              ),
              MenubarMenu(
                'Edit',
                items: [
                  MenuItem(
                    onPressed: () => picked.add('undo'),
                    child: const Text('Undo'),
                  ),
                ],
              ),
              MenubarMenu(
                'View',
                items: [
                  MenuItem(
                    onPressed: () => picked.add('zoom'),
                    child: const Text('Zoom in'),
                  ),
                ],
              ),
            ],
          ),
        ),
      );
      return picked;
    }

    testWidgets('a click opens a menu; pointing at the next switches to it', (
      tester,
    ) async {
      final semantics = tester.ensureSemantics();
      final picked = await bar(tester);
      await tester.tap(find.text('File'));
      await tester.pumpAndSettle();
      expect(find.text('New tab'), findsOneWidget);
      final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
      await mouse.addPointer(location: tester.getCenter(find.text('File')));
      await mouse.moveTo(tester.getCenter(find.text('Edit')));
      await tester.pumpAndSettle();
      expect(find.text('New tab'), findsNothing);
      expect(find.text('Undo'), findsOneWidget);
      await tester.tap(find.text('Undo'));
      await tester.pumpAndSettle();
      expect(picked, ['undo']);
      expect(tester.takeException(), isNull);
      semantics.dispose();
    });

    testWidgets('the arrows move between menus', (tester) async {
      await bar(tester);
      await tester.tap(find.text('File'));
      await tester.pumpAndSettle();
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowRight);
      await tester.pumpAndSettle();
      expect(find.text('Undo'), findsOneWidget);
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowLeft);
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowLeft);
      await tester.pumpAndSettle();
      expect(find.text('Zoom in'), findsOneWidget);
    });
  });
}
''',
    },
  ),
