          r'''// Ashlar UI: Navigation Menu. Copied into your app by `ashlar add navigation-menu`; it is
// yours to change.

import 'dart:async';

import 'package:ashlar_icons/ashlar_icons.dart';
import 'package:flutter/widgets.dart';

import 'popover.dart';
import 'pressable.dart';
import 'theme.dart';

/// One entry of a [NavigationMenu]: a link, or a heading that opens a panel of [content].
@immutable
class NavigationMenuItem {
  const NavigationMenuItem.link(
    this.label, {
    required VoidCallback this.onPressed,
  }) : content = null,
       width = 0;
  const NavigationMenuItem(
    this.label, {
    required WidgetBuilder this.content,
    this.width = 400,
  }) : onPressed = null;

  /// Its name in the bar.
  final String label;

  /// Called when it is chosen, for an item without a panel.
  final VoidCallback? onPressed;

  /// What its panel shows, usually links; null makes it a link itself.
  final WidgetBuilder? content;

  /// The panel's width.
  final double width;
}

/// A site's main navigation: links, and headings whose panels open on hover, on a click
/// or from the keyboard, with links and a line about each inside. Moving to another
/// heading while one is open moves the one panel across to it, its content sliding in.
///
/// ```dart
/// NavigationMenu(items: [
///   NavigationMenuItem('Components', content: (context) => Column(children: [
///     NavigationMenuLink(title: 'Button', description: 'Six variants and four sizes.', onPressed: () => go('/button')),
///   ])),
///   NavigationMenuItem.link('Docs', onPressed: () => go('/docs')),
/// ])
/// ```
class NavigationMenu extends StatefulWidget {
  const NavigationMenu({super.key, required this.items});

  /// The items along the bar.
  final List<NavigationMenuItem> items;

  @override
  State<NavigationMenu> createState() => _NavigationMenuState();
}

class _NavigationMenuState extends State<NavigationMenu> {
  // One panel for the whole bar: it moves to the heading being shown, and its content
  // slides across, rather than one panel closing and another opening.
  final _menu = MenuController();
  final _bar = GlobalKey();
  late final _keys = [for (final _ in widget.items) GlobalKey()];
  int? _open;

  /// Which way the content slides: towards the heading moved to.
  var _direction = 0;
  Timer? _timer;

  void _show(int i) {
    _timer?.cancel();
    setState(() {
      _direction = _open == null ? 0 : (i - _open!).sign;
      _open = i;
    });
    if (!_menu.isOpen) _menu.open();
  }

  /// Opens after a moment on hover, straight away if one is already open.
  void _hoverIn(int i) {
    _timer?.cancel();
    if (_open != null) return _show(i);
    _timer = Timer(
      const Duration(milliseconds: 200),
      () => mounted ? _show(i) : null,
    );
  }

  void _hoverOut() {
    _timer?.cancel();
    _timer = Timer(const Duration(milliseconds: 300), () {
      if (mounted) _menu.close();
    });
  }

  /// Heading [i]'s rectangle, from the bar's rectangle [bar] in the overlay.
  Rect _heading(Rect bar, int i) {
    final barBox = _bar.currentContext?.findRenderObject() as RenderBox?;
    final box = _keys[i].currentContext?.findRenderObject() as RenderBox?;
    if (barBox == null || box == null || !box.attached) return bar;
    return (bar.topLeft + box.localToGlobal(Offset.zero, ancestor: barBox)) &
        box.size;
  }

  @override
  void dispose() {
    _timer?.cancel();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    Widget trigger(int i, NavigationMenuItem item, {required bool open}) =>
        Pressable(
          link: item.onPressed != null,
          expanded: item.content == null ? null : open,
          onPressed: item.onPressed ?? () => open ? _menu.close() : _show(i),
          builder: (context, state) => AnimatedContainer(
            duration: t.duration,
            height: t.control(36),
            padding: const EdgeInsets.symmetric(horizontal: 16),
            alignment: Alignment.center,
            decoration: BoxDecoration(
              color: open || state.hovered
                  ? c.accent
                  : c.accent.withValues(alpha: 0),
              borderRadius: BorderRadius.circular(t.radiusMd),
              boxShadow: [if (state.focused) ...t.focusRing],
            ),
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(
                  item.label,
                  style: t.text.sm.copyWith(
                    fontWeight: FontWeight.w500,
                    color: open || state.hovered
                        ? c.accentForeground
                        : c.foreground,
                  ),
                ),
                if (item.content != null) ...[
                  const SizedBox(width: 4),
                  AnimatedRotation(
                    turns: open ? .5 : 0,
                    duration: t.duration,
                    child: AshlarIcon(
                      AshlarIconsRoundedStroke.chevronDown,
                      size: 12,
                      color: c.foreground,
                    ),
                  ),
                ],
              ],
            ),
          ),
        );
    return Semantics(
      container: true,
      label: 'Main',
      explicitChildNodes: true,
      child: RawMenuAnchor(
        controller: _menu,
        onClose: () => setState(() => _open = null),
        overlayBuilder: (context, info) {
          final i = _open;
          if (i == null) return const SizedBox.shrink();
          final item = widget.items[i];
          final still = MediaQuery.maybeDisableAnimationsOf(context) ?? false;
          final move = still ? Duration.zero : t.duration * 1.5;
          // The panel follows the heading: its place, width and height move together.
          return TweenAnimationBuilder<Rect?>(
            tween: RectTween(end: _heading(info.anchorRect, i)),
            duration: move,
            curve: Curves.easeOutCubic,
            builder: (context, at, child) => PopoverPanel(
              info: RawMenuOverlayInfo(
                anchorRect: at!,
                overlaySize: info.overlaySize,
                tapRegionGroupId: info.tapRegionGroupId,
                position: info.position,
              ),
              child: child!,
            ),
            child: MouseRegion(
              onEnter: (_) => _timer?.cancel(),
              onExit: (_) => _hoverOut(),
              child: FocusTraversalGroup(
                child: AnimatedContainer(
                  duration: move,
                  curve: Curves.easeOutCubic,
                  width: item.width,
                  // What leaves stays inside the panel as it changes size.
                  child: ClipRect(
                    child: AnimatedSize(
                      duration: move,
                      curve: Curves.easeOutCubic,
                      alignment: AlignmentDirectional.topStart,
                      child: AnimatedSwitcher(
                        duration: move,
                        // The new panel's content comes in from the side it was moved
                        // towards; the old goes the other way.
                        transitionBuilder: (child, animation) => FadeTransition(
                          opacity: animation,
                          child: SlideTransition(
                            position: Tween(
                              begin: Offset(
                                child.key == ValueKey(i)
                                    ? _direction * .15
                                    : -_direction * .15,
                                0,
                              ),
                              end: Offset.zero,
                            ).animate(animation),
                            child: child,
                          ),
                        ),
                        layoutBuilder: (current, previous) => Stack(
                          alignment: AlignmentDirectional.topStart,
                          children: [
                            for (final p in previous)
                              Positioned.fill(
                                child: IgnorePointer(
                                  child: ExcludeSemantics(child: p),
                                ),
                              ),
                            ?current,
                          ],
                        ),
                        child: KeyedSubtree(
                          key: ValueKey(i),
                          child: Padding(
                            padding: const EdgeInsets.all(8),
                            child: Builder(builder: item.content!),
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              ),
            ),
          );
        },
        child: Row(
          key: _bar,
          mainAxisSize: MainAxisSize.min,
          children: [
            for (final (i, item) in widget.items.indexed)
              KeyedSubtree(
                key: _keys[i],
                child: item.content == null
                    ? trigger(i, item, open: false)
                    : MouseRegion(
                        onEnter: (_) => _hoverIn(i),
                        onExit: (_) => _hoverOut(),
                        child: trigger(i, item, open: _open == i),
                      ),
              ),
          ],
        ),
      ),
    );
  }
}

/// A link in a navigation panel, with a line about where it goes. Picking it closes the
/// panel.
class NavigationMenuLink extends StatelessWidget {
  const NavigationMenuLink({
    super.key,
    required this.title,
    this.description,
    required this.onPressed,
  });

  /// The link's name.
  final String title;

  /// A line under the name: where it goes.
  final String? description;

  /// Called when it is chosen.
  final VoidCallback onPressed;

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    return Pressable(
      link: true,
      onPressed: () {
        MenuController.maybeOf(context)?.close();
        onPressed();
      },
      builder: (context, state) => AnimatedContainer(
        duration: t.duration,
        padding: const EdgeInsets.all(8),
        decoration: BoxDecoration(
          color: state.hovered || state.focused
              ? c.accent
              : c.accent.withValues(alpha: 0),
          borderRadius: BorderRadius.circular(t.radiusSm),
        ),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(
              title,
              style: t.text.sm.copyWith(
                fontWeight: FontWeight.w500,
                color: c.popoverForeground,
              ),
            ),
            if (description != null) ...[
              const SizedBox(height: 2),
              Text(
                description!,
                style: t.text.sm.copyWith(color: c.mutedForeground),
                maxLines: 2,
                overflow: TextOverflow.ellipsis,
              ),
            ],
          ],
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app"],
    tests: {
      'navigation_menu_test.dart':
          r'''// Tests for Navigation Menu. Copied into your app by `ashlar add navigation-menu` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/navigation_menu.dart';
import 'package:flutter/gestures.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child) => AshlarApp(home: Center(child: child));

Widget menu() => AshlarApp(
  home: Align(
    alignment: Alignment.topCenter,
    child: NavigationMenu(
      items: [
        NavigationMenuItem(
          'Products',
          width: 300,
          content: (context) =>
              NavigationMenuLink(title: 'Components', onPressed: () {}),
        ),
        NavigationMenuItem.link('Pricing', onPressed: () {}),
        NavigationMenuItem(
          'Company',
          width: 220,
          content: (context) =>
              NavigationMenuLink(title: 'About us', onPressed: () {}),
        ),
      ],
    ),
  ),
);

/// The panel: the box around a link's content.
Rect panelOf(WidgetTester tester, String link) => tester.getRect(
  find
      .ancestor(of: find.text(link), matching: find.byType(AnimatedContainer))
      .last,
);

void main() {
  testWidgets(
    'a navigation menu opens on hover after a moment; its links close it',
    (tester) async {
      final went = <String>[];
      await tester.pumpWidget(
        app(
          NavigationMenu(
            items: [
              NavigationMenuItem(
                'Components',
                content: (context) => NavigationMenuLink(
                  title: 'Button',
                  description: 'Six variants.',
                  onPressed: () => went.add('button'),
                ),
              ),
              NavigationMenuItem.link(
                'Docs',
                onPressed: () => went.add('docs'),
              ),
            ],
          ),
        ),
      );
      final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
      await mouse.addPointer(location: Offset.zero);
      await mouse.moveTo(tester.getCenter(find.text('Components')));
      await tester.pump(const Duration(milliseconds: 50));
      expect(find.text('Six variants.'), findsNothing);
      await tester.pump(const Duration(milliseconds: 300));
      await tester.pumpAndSettle();
      expect(find.text('Six variants.'), findsOneWidget);
      await mouse.moveTo(tester.getCenter(find.text('Button')));
      await tester.pump(const Duration(seconds: 1));
      await tester.tap(find.text('Button'));
      await tester.pumpAndSettle();
      expect(went, ['button']);
      expect(find.text('Six variants.'), findsNothing);
      await tester.tap(find.text('Docs'));
      expect(went, ['button', 'docs']);
    },
  );

  testWidgets('moving to another heading moves the one panel across to it', (
    tester,
  ) async {
    await tester.pumpWidget(menu());
    final mouse = await tester.createGesture(kind: PointerDeviceKind.mouse);
    await mouse.addPointer(location: Offset.zero);
    await mouse.moveTo(tester.getCenter(find.text('Products')));
    await tester.pump(const Duration(milliseconds: 300));
    await tester.pumpAndSettle();
    final first = panelOf(tester, 'Components');
    expect(first.width, closeTo(300, 1));

    await mouse.moveTo(tester.getCenter(find.text('Company')));
    await tester.pump();
    await tester.pump(const Duration(milliseconds: 60));
    // Midway: the panel is on its way, and both contents are there as one slides in.
    final going = panelOf(tester, 'About us');
    expect(going.left, greaterThan(first.left + 1));
    expect(going.left, lessThan(tester.getRect(find.text('Company')).left));
    await tester.pumpAndSettle();
    final last = panelOf(tester, 'About us');
    expect(last.width, closeTo(220, 1));
    expect(
      last.left,
      closeTo(
        tester
            .getRect(
              find
                  .ancestor(
                    of: find.text('Company'),
                    matching: find.byType(KeyedSubtree),
                  )
                  .first,
            )
            .left,
        2,
      ),
    );
    // The content it left has gone.
    expect(find.text('Components'), findsNothing);
  });

  testWidgets('Escape closes it, and a heading is said to be open or not', (
    tester,
  ) async {
    final semantics = tester.ensureSemantics();
    await tester.pumpWidget(menu());
    await tester.tap(find.text('Products'));
    await tester.pumpAndSettle();
    expect(find.text('Components'), findsOneWidget);
    expect(
      tester
          .getSemantics(find.text('Products'))
          .getSemanticsData()
          .flagsCollection
          .isExpanded,
      isNot(equals(null)),
    );
    await tester.sendKeyEvent(LogicalKeyboardKey.tab);
    await tester.sendKeyEvent(LogicalKeyboardKey.escape);
    await tester.pumpAndSettle();
    expect(find.text('Components'), findsNothing);
    semantics.dispose();
  });
}
