      'blocks/login_01.dart':
          r'''// Ashlar UI block: login-01. Copied into your app by `ashlar add login-01`; it is yours to
// change. A sign-in card in the middle of the page.

import 'package:flutter/widgets.dart';

import '../ui/button.dart';
import '../ui/card.dart';
import '../ui/form.dart';

/// A sign-in card: email and password, checked when sent.
class Login01 extends StatefulWidget {
  const Login01({
    super.key,
    this.onLogin,
    this.onForgot,
    this.onSignUp,
    this.onGoogle,
  });

