/// Sample navigation: sections of pages, one of them open.
const _sections = [
  ('Getting Started', ['Installation', 'Project Structure']),
  (
    'Build Your App',
    [
      'Routing',
      'Data Fetching',
      'Rendering',
      'State',
      'Styling',
      'Testing',
      'Accessibility',
      'Deploying',
    ],
  ),
  ('API Reference', ['Components', 'Widgets', 'Functions', 'CLI']),
