  ('Inbox', AshlarIconsRoundedStroke.inbox),
  ('Drafts', AshlarIconsRoundedStroke.file),
  ('Sent', AshlarIconsRoundedStroke.send),
  ('Junk', AshlarIconsRoundedStroke.archive),
