  'pull-to-refresh': Component(
    description:
        "A list that refreshes when pulled down from its top, with a Refresh action for screen readers.",
    requires: ["spinner", "theme"],
    packages: ["ashlar_icons"],
    block: false,
    files: {
      'pull_to_refresh.dart':
          r'''// Ashlar UI: Pull to Refresh. Copied into your app by `ashlar add pull-to-refresh`; it is
// yours to change.

import 'package:ashlar_icons/ashlar_icons.dart';
import 'package:flutter/semantics.dart';
import 'package:flutter/widgets.dart';

import 'spinner.dart';
import 'theme.dart';

/// A list that refreshes when pulled down from its top, as phone lists do: a spinner
/// shows how far to pull, then turns while [onRefresh] runs.
///
/// Works with both ways of scrolling: past the top with a bounce (iOS), or stopping at it
/// (Android). A screen reader is offered Refresh as an action instead of pulling. A mouse
/// does not pull a list, so on a desktop give a refresh button as well.
///
/// ```dart
/// PullToRefresh(
///   onRefresh: () => orders.reload(),
///   child: ListView(children: [for (final o in orders) Item(title: Text(o.name))]),
/// )
/// ```
class PullToRefresh extends StatefulWidget {
  const PullToRefresh({
    super.key,
    required this.onRefresh,
    required this.child,
    this.distance = 80,
    this.semanticLabel = 'Refresh',
  });

  /// Called once pulled far enough; the spinner turns until it completes.
  final Future<void> Function() onRefresh;

  /// The scrolling list.
  final Widget child;

  /// How far to pull before letting go refreshes.
  final double distance;

  /// What a screen reader calls the action.
  final String semanticLabel;

  @override
  State<PullToRefresh> createState() => _PullToRefreshState();
}

class _PullToRefreshState extends State<PullToRefresh>
    with SingleTickerProviderStateMixin {
  // How far it has been pulled past the top.
  double _pulled = 0;
  bool _dragging = false, _working = false;

  // How far the list itself is past its top, when it bounces.
  double _over = 0;
  bool _bounced = false;

  /// Holding the list down under the spinner while it turns, as a bouncing list does.
  bool _holding = false;
  late final AnimationController _back =
      AnimationController(
          vsync: this,
          duration: const Duration(milliseconds: 200),
        )
        ..addListener(() => setState(() => _pulled = _from * (1 - _back.value)))
        ..addStatusListener((s) {
          if (s == AnimationStatus.completed) setState(() => _holding = false);
        });
  double _from = 0;

  @override
  void dispose() {
    _back.dispose();
    super.dispose();
  }

  Future<void> _refresh() async {
    if (_working) return;
    setState(() {
      _working = true;
      _holding = _bounced;
      _pulled = widget.distance;
    });
    try {
      await widget.onRefresh();
    } finally {
      if (mounted) {
        setState(() => _working = false);
        _settle();
      }
    }
  }

  void _settle() {
    _from = _pulled;
    _back.forward(from: 0);
  }

  /// The finger has lifted: refresh if pulled far enough, otherwise let go.
  void _lifted() {
    _dragging = false;
    if (_pulled >= widget.distance) {
      _refresh();
    } else if (_pulled > 0) {
      _settle();
    }
  }

  bool _onScroll(ScrollNotification n) {
    if (n.depth != 0) return false;
    if (n is ScrollUpdateNotification) {
      final over = (n.metrics.minScrollExtent - n.metrics.pixels).clamp(
        0.0,
        double.infinity,
      );
      if (over != _over) setState(() => _over = over);
    }
    if (_working) return false;
    if (n is ScrollStartNotification && n.dragDetails != null) {
      _dragging = true;
      _bounced = false;
    }
    if (n is ScrollUpdateNotification && _dragging) {
      if (n.dragDetails == null) {
        // Moving on its own: the finger lifted and a bounce or fling began.
        _lifted();
        return false;
      }
      // Bouncing: the list itself goes past its top.
      if (n.metrics.pixels < n.metrics.minScrollExtent) {
        setState(() {
          _bounced = true;
          _pulled = n.metrics.minScrollExtent - n.metrics.pixels;
        });
      } else if (_pulled > 0 && n.scrollDelta! > 0) {
        // Pushed back up while pulled: the mark goes back with it.
        setState(
          () => _pulled = (_pulled - n.scrollDelta!).clamp(0, double.infinity),
        );
      }
    }
    // Stopping at the top: the pull is what it would have scrolled.
    if (n is OverscrollNotification &&
        n.dragDetails != null &&
        n.overscroll < 0) {
      setState(
        () => _pulled = (_pulled - n.overscroll * .5).clamp(
          0,
          widget.distance * 1.5,
        ),
      );
    }
    if (n is ScrollEndNotification && _dragging) _lifted();
    return false;
  }

  @override
  Widget build(BuildContext context) {
    final c = AshlarTheme.of(context).colors;
    final share = (_pulled / widget.distance).clamp(0.0, 1.0);
    return Semantics(
      customSemanticsActions: {
        CustomSemanticsAction(label: widget.semanticLabel): _refresh,
      },
      child: NotificationListener<ScrollNotification>(
        onNotification: _onScroll,
        child: Stack(
          children: [
            // What the list has bounced back, made up so the spinner has room.
            Transform.translate(
              offset: Offset(
                0,
                _holding ? (_pulled - _over).clamp(0, widget.distance) : 0,
              ),
              child: widget.child,
            ),
            if (_pulled > 0 || _working)
              Positioned(
                top: (_pulled.clamp(0, widget.distance) - 40) / 2 + 8,
                left: 0,
                right: 0,
                child: IgnorePointer(
                  child: Center(
                    child: Opacity(
                      opacity: _working ? 1 : share,
                      child: Container(
                        width: 32,
                        height: 32,
                        alignment: Alignment.center,
                        decoration: BoxDecoration(
                          color: c.popover,
                          shape: BoxShape.circle,
                          border: Border.all(color: c.border),
                        ),
                        child: _working
                            ? const Spinner(
                                size: 16,
                                semanticLabel: 'Refreshing',
                              )
                            // How far to go, as a turn of the mark: a full turn refreshes.
                            : Transform.rotate(
                                angle: share * 6.28,
                                child: AshlarIcon(
                                  AshlarIconsRoundedStroke.loaderCircle,
                                  size: 16,
                                  color: c.foreground,
                                ),
                              ),
                      ),
                    ),
                  ),
                ),
              ),
          ],
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app", "spinner"],
    tests: {
      'pull_to_refresh_test.dart':
          r'''// Tests for Pull To Refresh. Copied into your app by `ashlar add pull-to-refresh` with the component: they
// check what it promises, so change them as you change it.
import 'dart:async';

import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/pull_to_refresh.dart';
import 'package:ashlar_ui_gallery/ui/spinner.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter/semantics.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child, {TextDirection direction = TextDirection.ltr}) =>
    AshlarApp(
      builder: (context, page) =>
          Directionality(textDirection: direction, child: page!),
      home: child,
    );

void main() {
  group('Pull to Refresh', () {
    Future<Completer<void>> pumpList(
      WidgetTester tester,
      List<int> calls,
    ) async {
      final done = Completer<void>();
      await tester.pumpWidget(
        app(
          PullToRefresh(
            onRefresh: () {
              calls.add(1);
              return done.future;
            },
            child: ListView(
              children: [
                for (var i = 0; i < 30; i++)
                  SizedBox(height: 50, child: Text('Order $i')),
              ],
            ),
          ),
        ),
      );
      return done;
    }

    for (final platform in [TargetPlatform.android, TargetPlatform.iOS]) {
      testWidgets('pulled far enough, it refreshes, on ${platform.name}', (
        tester,
      ) async {
        debugDefaultTargetPlatformOverride = platform;
        try {
          final calls = <int>[];
          final done = await pumpList(tester, calls);
          await tester.fling(find.text('Order 2'), const Offset(0, 400), 400);
          await tester.pump();
          await tester.pump(const Duration(milliseconds: 100));
          expect(calls, [1]);
          expect(find.bySemanticsLabel('Refreshing'), findsOneWidget);
          done.complete();
          await tester.pumpAndSettle();
          expect(find.bySemanticsLabel('Refreshing'), findsNothing);
        } finally {
          debugDefaultTargetPlatformOverride = null;
        }
      });
    }

    testWidgets('a bouncing list is held under the spinner while it turns', (
      tester,
    ) async {
      debugDefaultTargetPlatformOverride = TargetPlatform.iOS;
      try {
        final calls = <int>[];
        final done = await pumpList(tester, calls);
        await tester.fling(find.text('Order 2'), const Offset(0, 400), 400);
        // The bounce back has finished; the refresh has not.
        for (var i = 0; i < 30; i++) {
          await tester.pump(const Duration(milliseconds: 50));
        }
        expect(calls, [1]);
        final spinner = tester.getRect(find.byType(Spinner));
        expect(
          tester.getRect(find.text('Order 0')).top,
          greaterThanOrEqualTo(spinner.bottom),
        );
        done.complete();
        await tester.pumpAndSettle();
        expect(tester.getRect(find.text('Order 0')).top, 0);
      } finally {
        debugDefaultTargetPlatformOverride = null;
      }
    });

    testWidgets('a short pull does not', (tester) async {
      final calls = <int>[];
      await pumpList(tester, calls);
      await tester.drag(find.text('Order 2'), const Offset(0, 40));
      await tester.pumpAndSettle();
      expect(calls, isEmpty);
    });

    testWidgets('a screen reader refreshes without pulling', (tester) async {
      final semantics = tester.ensureSemantics();
      final calls = <int>[];
      final done = await pumpList(tester, calls);
      final node = tester.getSemantics(find.byType(PullToRefresh));
      final id = node.getSemanticsData().customSemanticsActionIds!.single;
      expect(CustomSemanticsAction.getAction(id)!.label, 'Refresh');
      node.owner!.performAction(node.id, SemanticsAction.customAction, id);
      await tester.pump();
      expect(calls, [1]);
      done.complete();
      await tester.pumpAndSettle();
      semantics.dispose();
    });
  });
}
''',
    },
  ),
  'bottom-bar': Component(
    description:
        "An app's main places along the bottom of a phone screen, an icon and a name each.",
    requires: ["pressable", "theme"],
    packages: [],
    block: false,
    files: {
      'bottom_bar.dart':
          r'''// Ashlar UI: Bottom Bar. Copied into your app by `ashlar add bottom-bar`; it is yours to
// change.

import 'dart:ui' show SemanticsRole;

import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';

import 'pressable.dart';
import 'theme.dart';

/// One place in a [BottomBar].
@immutable
class BottomBarItem {
  const BottomBarItem({
    required this.label,
    required this.icon,
    this.activeIcon,
    this.badge,
  });

  /// Its name, under the icon.
  final String label;
  final Widget icon;

  /// Shown instead of [icon] while it is the place you are: a filled icon, say.
  final Widget? activeIcon;

  /// A count to show on the icon: unread messages. Null shows none.
  final String? badge;
}

/// An app's main places along the bottom of a phone screen, an icon and a name each,
/// above the home indicator. Two to five places; the one you are in stands out.
///
/// To a screen reader it is a tab bar; from a keyboard, the arrow keys move along it.
///
/// ```dart
/// BottomBar(
///   index: page,
///   onChanged: (i) => setState(() => page = i),
///   items: [
///     BottomBarItem(label: 'Home', icon: AshlarIcon(AshlarIconsRoundedStroke.house)),
///     BottomBarItem(label: 'Inbox', icon: AshlarIcon(AshlarIconsRoundedStroke.inbox), badge: '3'),
///   ],
/// )
/// ```
class BottomBar extends StatelessWidget {
  const BottomBar({
    super.key,
    required this.items,
    required this.index,
    required this.onChanged,
  }) : assert(items.length >= 2 && items.length <= 5);

  final List<BottomBarItem> items;

  /// The place you are in.
  final int index;

  /// Told the place chosen.
  final ValueChanged<int> onChanged;

  @override
  Widget build(BuildContext context) {
    final t = AshlarTheme.of(context);
    final c = t.colors;
    final rtl = isRtl(context);
    void step(int by) => onChanged((index + (rtl ? -by : by)) % items.length);
    return DecoratedBox(
      decoration: BoxDecoration(
        color: c.background,
        border: Border(top: BorderSide(color: c.border)),
      ),
      child: SafeArea(
        top: false,
        child: CallbackShortcuts(
          bindings: {
            const SingleActivator(LogicalKeyboardKey.arrowRight): () => step(1),
            const SingleActivator(LogicalKeyboardKey.arrowLeft): () => step(-1),
          },
          child: Semantics(
            role: SemanticsRole.tabBar,
            container: true,
            explicitChildNodes: true,
            child: SizedBox(
              height: 56,
              child: Row(
                children: [
                  for (final (i, item) in items.indexed)
                    Expanded(
                      child: Pressable(
                        role: SemanticsRole.tab,
                        selected: i == index,
                        semanticLabel: item.badge == null
                            ? item.label
                            : '${item.label}, ${item.badge}',
                        onPressed: () => onChanged(i),
                        builder: (context, state) {
                          final on = i == index;
                          final ink = on ? c.foreground : c.mutedForeground;
                          return AnimatedContainer(
                            duration: t.duration,
                            margin: const EdgeInsets.all(4),
                            decoration: BoxDecoration(
                              color: state.hovered
                                  ? c.muted
                                  : c.muted.withValues(alpha: 0),
                              borderRadius: BorderRadius.circular(t.radiusMd),
                              border: state.focused
                                  ? Border.all(color: c.ring, width: 2)
                                  : null,
                            ),
                            child: Column(
                              mainAxisAlignment: MainAxisAlignment.center,
                              children: [
                                Stack(
                                  clipBehavior: Clip.none,
                                  children: [
                                    IconTheme.merge(
                                      data: IconThemeData(color: ink, size: 22),
                                      child: on
                                          ? item.activeIcon ?? item.icon
                                          : item.icon,
                                    ),
                                    if (item.badge != null)
                                      PositionedDirectional(
                                        top: -4,
                                        end: -10,
                                        child: Container(
                                          constraints: const BoxConstraints(
                                            minWidth: 16,
                                          ),
                                          padding: const EdgeInsets.symmetric(
                                            horizontal: 4,
                                          ),
                                          height: 16,
                                          alignment: Alignment.center,
                                          decoration: BoxDecoration(
                                            color: c.destructive,
                                            borderRadius: BorderRadius.circular(
                                              8,
                                            ),
                                            border: Border.all(
                                              color: c.background,
                                              width: 1.5,
                                            ),
                                          ),
                                          child: Text(
                                            item.badge!,
                                            style: t.text.xs.copyWith(
                                              fontSize: 10,
                                              height: 1,
                                              color: c.destructiveForeground,
                                              fontWeight: FontWeight.w600,
                                            ),
                                          ),
                                        ),
                                      ),
                                  ],
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  item.label,
                                  maxLines: 1,
                                  overflow: TextOverflow.ellipsis,
                                  style: t.text.xs.copyWith(
                                    color: ink,
                                    fontWeight: on
                                        ? FontWeight.w600
                                        : FontWeight.w500,
                                  ),
                                ),
                              ],
                            ),
                          );
                        },
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}
''',
    },
    testNeeds: ["app"],
    tests: {
      'bottom_bar_test.dart':
          r'''// Tests for Bottom Bar. Copied into your app by `ashlar add bottom-bar` with the component: they
// check what it promises, so change them as you change it.
import 'package:ashlar_ui_gallery/ui/app.dart';
import 'package:ashlar_ui_gallery/ui/bottom_bar.dart';
import 'package:flutter/semantics.dart';
import 'package:flutter/services.dart';
import 'package:flutter/widgets.dart';
import 'package:flutter_test/flutter_test.dart';

Widget app(Widget child, {TextDirection direction = TextDirection.ltr}) =>
    AshlarApp(
      builder: (context, page) =>
          Directionality(textDirection: direction, child: page!),
      home: child,
    );

void main() {
  group('Bottom Bar', () {
    testWidgets('a tap, or the arrow keys, choose a place; it is a tab bar', (
      tester,
    ) async {
      final semantics = tester.ensureSemantics();
      var page = 0;
      await tester.pumpWidget(
        app(
          StatefulBuilder(
            builder: (context, set) => Align(
              alignment: Alignment.bottomCenter,
              child: BottomBar(
                index: page,
                onChanged: (i) => set(() => page = i),
                items: const [
                  BottomBarItem(label: 'Home', icon: Text('H')),
                  BottomBarItem(label: 'Inbox', icon: Text('I'), badge: '3'),
                  BottomBarItem(label: 'Profile', icon: Text('P')),
                ],
              ),
            ),
          ),
        ),
      );
      await tester.tap(find.text('Inbox'));
      await tester.pump();
      expect(page, 1);
      final inbox = tester
          .getSemantics(find.bySemanticsLabel('Inbox, 3'))
          .getSemanticsData();
      expect(inbox.role, SemanticsRole.tab);
      expect(inbox.flagsCollection.isSelected, isNotNull);
      await tester.sendKeyEvent(LogicalKeyboardKey.tab);
      await tester.sendKeyEvent(LogicalKeyboardKey.arrowRight);
      await tester.pump();
      expect(page, 2);
      semantics.dispose();
    });

    testWidgets('it rises above the home indicator by its height', (
      tester,
    ) async {
      Future<double> homeBottom() async {
        await tester.pumpWidget(
          app(
            Align(
              alignment: Alignment.bottomCenter,
              child: BottomBar(
                index: 0,
                onChanged: (_) {},
                items: const [
                  BottomBarItem(label: 'Home', icon: Text('H')),
                  BottomBarItem(label: 'Inbox', icon: Text('I')),
                ],
              ),
            ),
          ),
        );
        return tester.getRect(find.text('Home')).bottom;
      }

      final without = await homeBottom();
      // 34 physical pixels of home indicator.
      tester.view.padding = const FakeViewPadding(bottom: 34);
      addTearDown(tester.view.reset);
      final within = await homeBottom();
      expect(without - within, closeTo(34 / tester.view.devicePixelRatio, .01));
    });
  });
}
''',
    },
  ),
};
